/*
 * Every call sits inside `if (__DEV__)`, and so does diagnostic-only state: a dedupe
 * latch lives inside a helper called that way (`warnWriteOnce`), and a count that
 * crosses a function boundary is a dev-only optional callback. A value in expression
 * position uses `__DEV__ ? x : y`. A bare call ships its text in the min build, and an
 * ungated latch keeps the branch that reads it.
 *
 * Never gate a failure that can first occur in production. These `err` sites are bare
 * on purpose: `invokeHandler`, `runCleanups`, a scope's `setup`/`connect`/`disconnect`,
 * `rz-store`'s JSON parse and seed check, and the catches in `runFetch`,
 * `sendAndRoute`, and `_sendAndApply`, which settle a thrown request as
 * `INTERNAL_ERROR` and leave the report as the only trace of what threw. The URL catch
 * in `StoreSync._request` is bare for the same reason: it records `INTERNAL_ERROR`
 * without firing request events. The restore and save reports in
 * `reactivity/persist.ts` depend on browser storage state, not markup.
 *
 * Messages: never write `[Rouse]`. Lead with an `rz-<slug>:` label and a lowercase word
 * only when one directive is clearly the entry point; shared internals (parsers,
 * `setNestedVal`, `invokeHandler`) read as plain sentences. Quote identifiers and values
 * in single quotes, write stores as `@store`, name the fix as an imperative follow-on,
 * end with a period, and pass `el` last (`err('…', el, error)`).
 *
 * Throws are control flow: never gated, never labeled, always through `fail()`, which
 * returns `never`. Payload-layer sites pass `TypeError` to mirror native `fetch()`.
 */
export function info(msg: string, ...args: any[]) {
  console.info(`[Rouse] ${msg}`, ...args);
}

export function warn(msg: string, ...args: any[]) {
  console.warn(`[Rouse] ${msg}`, ...args);
}

export function err(msg: string, ...args: any[]) {
  console.error(`[Rouse] ${msg}`, ...args);
}

export function fail(
  msg: string,
  ErrorClass: typeof Error | typeof TypeError = Error,
  options?: ErrorOptions,
): never {
  throw new ErrorClass(`[Rouse] ${msg}`, options);
}
